        },
        {
          "name": "x_pack",
          "expression": {"op": "greedy_independent_weight", "args": [{"op": "difference", "args": [{"op": "available", "args": []}, {"op": "singleton", "args": [{"op": "root", "args": []}]}]}]}
        },
        {
          "name": "x_cover",
          "expression": {"op": "clique_cover_weight", "args": [{"op": "difference", "args": [{"op": "available", "args": []}, {"op": "singleton", "args": [{"op": "root", "args": []}]}]}]}
        },
        {
          "name": "n_edges",
          "expression": {"op": "count", "args": [{"op": "induced_edges", "args": [{"op": "neighbors", "args": [{"op": "root", "args": []}]}]}]}
        },
        {
          "name": "r_edges",
          "expression": {"op": "count", "args": [{"op": "induced_edges", "args": [{"op": "difference", "args": [{"op": "difference", "args": [{"op": "available", "args": []}, {"op": "neighbors", "args": [{"op": "root", "args": []}]}]}, {"op": "singleton", "args": [{"op": "root", "args": []}]}]}]}]}
        }
      ],
      "rule": "(weight+r_pack-x_pack) + 0.35*(weight+r_cover-x_cover) + 0.025*n_edges/max(1e-9,abs(1+degree)) - 0.025*r_edges/max(1e-9,abs(1+compatible_weight))",
      "rationale": "Tests polynomial inclusion-versus-exclusion margins as an opportunity-cost estimate. Residual and neighborhood edge summaries provide distinctions beyond packing and cover totals."
    },
    {
      "name": "cover_boundary_loss",
      "features": [
